46	const PROCESSING_FEE = 5;
47	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
48	const LOYALTY_DISCOUNT_RATE = 0.2;
49	const LOYALTY_YEARS_THRESHOLD = 2;
50	const CURSE_SURCHARGE_RATE = 0.5;
51	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
52	const HIGH_ENCHANTMENT_THRESHOLD = 5;
53	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
54	  sword: 100,
55	  amulet: 60,
56	  staff: 80,
57	  potion: 40,
58	  rune: 25,
59	  moonstone: 25,
60	};
61	const ALIKE_BLOCK_SIZE = 3;
62	const ALIKE_BLOCK_PREMIUM = 60;
63	
64	// Premiums are rounded up to whole G, in the MHPCO's favor.
65	const roundPremiumInFavorOfMHPCO = (amount: number): number => Math.ceil(amount);
66	
67	const countByType = (items: Item[]): Map<string, number> =>
68	  items.reduce(
69	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
70	    new Map<string, number>(),
71	  );
72	
73	// Exactly three alike items form a discounted block; any other count is priced per item.
74	const alikeItemsPremium = (type: string, count: number): number =>
75	  count === ALIKE_BLOCK_SIZE
76	    ? ALIKE_BLOCK_PREMIUM
77	    : count * BASE_PREMIUM_BY_TYPE[type];
78	
79	const policyBasePremium = (items: Item[]): number =>
80	  [...countByType(items)].reduce(
81	    (sum, [type, count]) => sum + alikeItemsPremium(type, count),
82	    0,
83	  );
84	
85	// Item-specific modifiers apply to the affected item's own base premium.
86	interface ItemRiskModifier {
87	  appliesTo: (item: Item) => boolean;
88	  rate: number;
89	}
90	
91	const ITEM_RISK_MODIFIERS: ItemRiskModifier[] = [
92	  { appliesTo: (item) => item.cursed === true, rate: CURSE_SURCHARGE_RATE },
93	  {
94	    appliesTo: (item) => (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_THRESHOLD,
95	    rate: HIGH_ENCHANTMENT_SURCHARGE_RATE,
96	  },
97	];
98	
99	const itemRiskSurchargeRate = (item: Item): number =>
100	  ITEM_RISK_MODIFIERS.filter((modifier) => modifier.appliesTo(item)).reduce(
101	    (rate, modifier) => rate + modifier.rate,
102	    0,
103	  );
104	
105	const itemRiskSurcharges = (items: Item[]): number =>
106	  items.reduce(
107	    (sum, item) =>
108	      sum + BASE_PREMIUM_BY_TYPE[item.type] * itemRiskSurchargeRate(item),
109	    0,
110	  );
111	
112	const quotePremium = (items: Item[], yearsWithMHPCO: number): number => {
113	  const basePremium = policyBasePremium(items);
114	  // Policy-wide modifiers apply to the policy base premium.
115	  const firstInsuranceSurcharge = basePremium * FIRST_INSURANCE_SURCHARGE_RATE;
116	  const loyaltyDiscount =
117	    yearsWithMHPCO >= LOYALTY_YEARS_THRESHOLD
118	      ? basePremium * LOYALTY_DISCOUNT_RATE
119	      : 0;
120	  return roundPremiumInFavorOfMHPCO(
121	    basePremium +
122	      itemRiskSurcharges(items) +
123	      firstInsuranceSurcharge -
124	      loyaltyDiscount +
125	      PROCESSING_FEE,
126	  );
127	};
128	
129	export const runScenario = (scenario: Scenario): ScenarioResult => {
130	  const step = scenario.steps[0] as QuoteStep;
131	  return {
132	    results: [
133	      { premium: quotePremium(step.items, scenario.customer.yearsWithMHPCO) },
134	    ],
135	  };
136	};
